<?php
require "config.php";
$user = requireLogin();
$members = $conn->query("SELECT u.id, u.display_name, u.avatar_path, u.academic_level, u.profile_visibility, COUNT(r.id) AS shared_count, GROUP_CONCAT(DISTINCT a.label ORDER BY a.id SEPARATOR ', ') AS shared_levels FROM users u LEFT JOIN resources r ON r.submitted_by = u.id AND r.status = 'approved' LEFT JOIN academic_levels a ON a.id = r.academic_level_id GROUP BY u.id, u.display_name, u.avatar_path, u.academic_level, u.profile_visibility ORDER BY u.display_name");
?>
<!doctype html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Members | Resource Exchange</title><link rel="stylesheet" href="style.css?v=privacy-6"></head><body>
<header class="topbar"><a class="brand" href="index.php">Student Resource Exchange</a><nav><?php if ($user["role"] === "admin"): ?><a href="admin.php">Admin page</a><?php else: ?><a href="student.php">Student page</a><?php endif; ?><a class="active" href="users.php">Members</a><a href="profile.php">Profile</a><a href="logout.php">Log out</a></nav></header>
<main class="container"><section class="hero"><p class="eyebrow">COMMUNITY MEMBERS</p><h1>Meet the resource-sharing community.</h1><p>View public member information and discover who has contributed approved study resources. Email addresses and private account details are never shown.</p></section><section class="panel"><div class="member-grid"><?php if (!$members->num_rows): ?><p class="muted">No members are available yet.</p><?php endif; ?><?php while ($member = $members->fetch_assoc()): ?><article class="member-card"><img class="member-avatar" src="<?= e(avatarUrl($member["avatar_path"] ?? null)) ?>" alt="<?= e($member["display_name"]) ?> profile picture" width="72" height="72" loading="lazy"><h2><?= e($member["display_name"]) ?></h2><p class="member-levels"><strong>Academic level:</strong> <?= e($member["academic_level"] ?: "Not provided") ?></p><?php if (($member["profile_visibility"] ?? "public") === "private"): ?><p class="private-label">Shared resources are private</p><?php else: ?><p class="muted"><?= (int) $member["shared_count"] ?> approved resource<?= (int) $member["shared_count"] === 1 ? "" : "s" ?> shared</p><?php endif; ?><a class="download" href="user_profile.php?id=<?= (int) $member["id"] ?>">View profile</a></article><?php endwhile; ?></div></section></main></body></html>
